SELECT p.gender, a.admission_type_id, s.stay_length_of_day, i.itemid, SUM(CASE WHEN p.dod IS NOT NULL THEN 1 ELSE 0 END)::FLOAT / NULLIF(COUNT(p.subject_id), 0) AS mortality_rate, COUNT(d.icd_code) AS avg_comorbidity_count, (COUNT(d.icd_code) - COUNT(DISTINCT CASE WHEN p.dod IS NOT NULL THEN d.icd_code END)) AS comorbidity_difference FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN icustays s ON a.stay_id = s.stay_id JOIN labevents l ON a.subject_id = l.subject_id AND a.hadm_id = l.hadm_id JOIN diagnoses_icd d ON a.subject_id = d.subject_id AND a.hadm_id = d.hadm_id WHERE p.gender = 'M' AND EXTRACT(YEAR FROM age(CURRENT_DATE, p.birth_date)) = 44 AND a.admittime BETWEEN '2015-01-01' AND '2018-12-31' AND (l.value = 'Aspiration' OR l.value = 'Pneumonia') AND (s.stay_length_of_day BETWEEN 1 AND 3 OR (s.stay_length_of_day BETWEEN 4 AND 7 AND i.itemid IN (57027, 57028, 57029)) OR s.stay_length_of_day >= 8) GROUP BY p.gender, a.admission_type_id, s.stay_length_of_day, i.itemid ORDER BY p.gender, a.admission_type_id, s.stay_length_of_day, i.itemid NULLS LAST;